workers.script:
// Child worker reachable via service binding (both legacy and RPC style).
// The parent worker calls both env.CHILD_SVC.fetch(...) AND env.CHILD_RPC.ping().
export class ChildEntrypoint {
  async ping() { return 'pong-from-rpc'; }
  async echo(x) { return { echoed: x, by: 'child-rpc' }; }
}
export default {
  async fetch(request) {
    return new Response(JSON.stringify({ from: 'child-svc', via: 'fetch' }), { headers: { 'Content-Type': 'application/json' } });
  },
};

// MaxWorker — exercises every binding type the engine supports.
//
// Each route validates ONE binding so the post-migration runtime smoke
// test (if run) can hit each endpoint and confirm the binding is wired.

export class MaxWorkerDO {
  constructor(state) { this.state = state; }
  async fetch(request) {
    const url = new URL(request.url);
    if (url.pathname === '/incr') {
      const c = (await this.state.storage.get('count') || 0) + 1;
      await this.state.storage.put('count', c);
      return Response.json({ count: c });
    }
    return Response.json({ do: 'MaxWorkerDO' });
  }
}

export class MaxWorkerWorkflow {
  async run(event, step) {
    await step.do('step-1', async () => ({ ok: true }));
    return { workflowRan: true };
  }
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const path = url.pathname;
    try {
      // 1. KV (primary)
      if (path === '/kv') {
        const v = await env.KV_PRIMARY.get('config:version');
        return Response.json({ binding: 'kv_namespace', name: 'KV_PRIMARY', value: v });
      }
      // 2. KV (secondary — multiple bindings of same type)
      if (path === '/kv2') {
        const v = await env.KV_SECONDARY.get('session:abc');
        return Response.json({ binding: 'kv_namespace', name: 'KV_SECONDARY', value: v });
      }
      // 3. R2
      if (path === '/r2') {
        const obj = await env.R2.get('config.json');
        const text = obj ? await obj.text() : null;
        return Response.json({ binding: 'r2_bucket', value: text });
      }
      // 4. D1
      if (path === '/d1') {
        const r = await env.D1.prepare('SELECT * FROM feature_flags').all();
        return Response.json({ binding: 'd1', rows: r.results });
      }
      // 5. Queues (producer side)
      if (path === '/queue') {
        await env.QUEUE.send({ ts: Date.now(), source: 'maxworker' });
        return Response.json({ binding: 'queue', sent: true });
      }
      // 6. Durable Object
      if (path === '/do') {
        const id = env.DO.idFromName('default');
        return env.DO.get(id).fetch(new Request(url.origin + '/incr'));
      }
      // 7. Service binding (fetch style)
      if (path === '/svc') {
        return env.CHILD_SVC.fetch(request);
      }
      // 8. Service binding (RPC style — entrypoint set)
      if (path === '/svc-rpc') {
        const v = await env.CHILD_RPC.ping();
        return Response.json({ binding: 'service-rpc', value: v });
      }
      // 9. Secret
      if (path === '/secret') {
        return new Response(JSON.stringify({ binding: 'secret_text', len: (env.SECRET || '').length }), { headers: { 'Content-Type': 'application/json' } });
      }
      // 10. Workers AI
      if (path === '/ai') {
        // Smoke test: just confirm the binding object exists
        const present = typeof env.AI?.run === 'function';
        return Response.json({ binding: 'ai', has_run: present });
      }
      // 11. Analytics Engine
      if (path === '/ae') {
        env.ANALYTICS.writeDataPoint({ blobs: ['test'], doubles: [1.0], indexes: ['idx'] });
        return Response.json({ binding: 'analytics_engine', wrote: true });
      }
      // 12. Browser Rendering
      if (path === '/browser') {
        const has = typeof env.BROWSER?.fetch === 'function' || typeof env.BROWSER === 'object';
        return Response.json({ binding: 'browser', present: has });
      }
      // 13. Vectorize
      if (path === '/vec') {
        const has = typeof env.VECTORIZE?.query === 'function';
        return Response.json({ binding: 'vectorize', has_query: has });
      }
      // 14. Send Email
      if (path === '/email') {
        const has = typeof env.EMAIL?.send === 'function';
        return Response.json({ binding: 'send_email', has_send: has });
      }
      // 15. Workflow binding
      if (path === '/workflow') {
        const has = typeof env.WORKFLOW?.create === 'function';
        return Response.json({ binding: 'workflow', has_create: has });
      }
      // 16. Dispatch namespace (Workers for Platforms)
      if (path === '/dispatch') {
        const has = typeof env.DISPATCH?.get === 'function';
        return Response.json({ binding: 'dispatch_namespace', has_get: has });
      }
      // 17. Pipelines
      if (path === '/pipeline') {
        const has = typeof env.PIPELINE?.send === 'function';
        return Response.json({ binding: 'pipelines', has_send: has });
      }
      // 18. Version metadata
      if (path === '/version') {
        return Response.json({ binding: 'version_metadata', value: env.VERSION_META });
      }
      // 19. Assets binding
      if (path === '/asset') {
        const has = typeof env.ASSETS?.fetch === 'function';
        return Response.json({ binding: 'assets', has_fetch: has });
      }
      // 20. Rate Limit binding
      if (path === '/rate') {
        const r = env.RATE_LIMITER ? await env.RATE_LIMITER.limit({ key: 'test-key' }) : null;
        return Response.json({ binding: 'rate_limit', result: r });
      }
      // 21. JSON binding
      if (path === '/json') {
        return Response.json({ binding: 'json', value: env.CONFIG_JSON });
      }
      // 22. Plain text binding
      if (path === '/text') {
        return Response.json({ binding: 'plain_text', value: env.PLAIN_GREETING });
      }
      // 23. Hyperdrive (manual binding — surface presence only)
      if (path === '/hyperdrive') {
        const has = !!env.HYPERDRIVE;
        return Response.json({ binding: 'hyperdrive', present: has });
      }
      // 24. mTLS Certificate (manual binding)
      if (path === '/mtls') {
        const has = !!env.MTLS_CERT;
        return Response.json({ binding: 'mtls_certificate', present: has });
      }
      // 25. Secrets Store (manual binding)
      if (path === '/store-secret') {
        const has = !!env.STORE_SECRET;
        return Response.json({ binding: 'secrets_store_secret', present: has });
      }
      // 26. VPC Service binding (manual binding)
      if (path === '/vpc') {
        const has = !!env.VPC_BACKEND;
        return Response.json({ binding: 'vpc_service', present: has });
      }

      // Self-test endpoint: list every binding that's present on env
      if (path === '/bindings') {
        const present = Object.keys(env).filter(k => env[k] !== undefined);
        return Response.json({ worker: 'maxworker-zone-worker', bindings_present: present });
      }

      return new Response('MaxWorker — try /bindings to list', { status: 200 });
    } catch (e) {
      return new Response(String(e?.message || e), { status: 500 });
    }
  },
};
